const rad=x=>x*Math.PI/180;
const metalMass=volume=>volume*C.density/1e9;
export function bridgeMetalMass(variant='light') {
  if(variant==='original')return .1279152;
  const Ao=C.bridgeWidth*C.bridgeHeight;
  const Ai=(C.bridgeWidth-2*C.bridgeWall)*(C.bridgeHeight-2*C.bridgeWall);
  return metalMass((Ao-Ai)*(C.bridgeLength-C.bridgeSolidLength)+Ao*C.bridgeSolidLength);
}
export function deckMetalMass(variant='light') {
  if(variant==='original')return .546947532;
  const L=C.deckLength,B=C.deckWidth,t=C.deckSkin,w=C.deckRibWall,d=C.deckRibDepth;
  return metalMass(L*B*t+(L*B-(L-2*w)*(B-2*w))*d+3*(L-2*w)*w*d);
}
const member=(serviceStress,serviceDeflection,extra={})=>({
  serviceStress, designStress:serviceStress*C.loadFactor,
  serviceDeflection, designDeflection:serviceDeflection*C.loadFactor,
  yieldMargin:C.yieldMPa/(serviceStress*C.loadFactor),
  stressWithinYield:serviceStress*C.loadFactor<=C.yieldMPa,
  serviceDeflectionWithinTarget:serviceDeflection<=C.serviceDeflectionLimitMm,
  ...extra,
});

export function calculateLightweight(options={}) {
  const {bookMass=5,angle=55,thickness=50,variant='light',extraMass=.1}=options;
  if(!['light','original'].includes(variant)||![bookMass,angle,thickness,extraMass].every(Number.isFinite)||bookMass<0||bookMass>5||angle<30||angle>75||thickness<25||thickness>50||extraMass<0)throw Error('계산 범위: 책 0–5 kg, 30–75°, 두께 25–50 mm, 양의 추가 질량');
  const a=rad(angle),c=Math.cos(a),s=Math.sin(a);
  const bookComY=C.pivotY-51*c-(thickness/2+22)*s;
  const bookComZ=C.pivotZ-51*s+(thickness/2+22)*c;
  let movingMass=0, movingFirstMoment=0, hingeFirstMoment=0;
  for(const p of MOVING_ORIGINAL) {
    const mass=p.name.includes('transverse bridge')?bridgeMetalMass(variant):p.massKg;
    const y=p.rotates?C.pivotY+p.localAlongMm*c-p.localNormalMm*s:p.centroidMm[1];
    movingMass+=mass;
    movingFirstMoment+=mass*(C.postY-y);
    if(p.rotates)hingeFirstMoment+=mass*(C.pivotY-y);
  }
  const payloadMass=bookMass+extraMass;
  const totalMass=payloadMass+movingMass;
  const totalF=totalMass*C.g;
  const totalM=Math.abs(C.g*(payloadMass*(C.postY-bookComY)+movingFirstMoment));
  const jointM=Math.abs(C.g*(payloadMass*(C.pivotY-bookComY)+hingeFirstMoment));
  const N=C.heavyShare*totalF,M=C.heavyShare*totalM;
  const b=C.postOuter,bi=variant==='light'?b-2*C.postWall:0;
  // Actual mesh section includes the small outer corner rounds; bore is 6 mm square.
  const A=variant==='light'?C.postLightArea:C.postLightArea+36;
  const I=variant==='light'?C.postLightI:C.postLightI+108,Z=I/(b/2),L=C.postFreeLength;
  const post=member(N/A+M/Z,M*L**2/(2*C.E*I),{
    axialN:N,designAxialN:N*C.loadFactor,momentNmm:M,designMomentNmm:M*C.loadFactor,A,I,Z,
    eulerLoadN:Math.PI**2*C.E*I/(2*L)**2,
    unrestrained190mmDeflection:M*C.postFullLength**2/(2*C.E*I),
    metalMassKg:variant==='light'?2*metalMass(A*(190-20)+64*20):.0655641054,
  });
  const bw=C.bridgeWidth,bh=C.bridgeHeight,bt=C.bridgeWall;
  const bI=variant==='light'?(bw*bh**3-(bw-2*bt)*(bh-2*bt)**3)/12:bw*bh**3/12;
  const bZ=bI/(bh/2),bL=C.bridgeClearSpan;
  const bendStress=totalF*bL/(4*bZ);
  let torsionShear,J;
  if(variant==='light') {
    const Am=(bw-bt)*(bh-bt);
    torsionShear=totalM/(2*Am*bt);
    J=4*Am**2/(2*(bw-bt+bh-bt)/bt);
  } else {
    // Saint-Venant rectangular-bar Fourier solution (odd positive n).
    let sj=0,st=0;
    for(let n=1;n<200;n+=2){sj+=Math.tanh(n*Math.PI*bw/(2*bh))/n**5;st+=1/(n*n*Math.cosh(n*Math.PI*bw/(2*bh)));}
    J=bw*bh**3/3*(1-192*bh/(Math.PI**5*bw)*sj);
    torsionShear=totalM*bh*(1-8/Math.PI**2*st)/J;
  }
  const bridge=member(Math.hypot(bendStress,Math.sqrt(3)*torsionShear),totalF*bL**3/(48*C.E*bI),{
    serviceBendingStress:bendStress,designBendingStress:bendStress*C.loadFactor,
    serviceTorsionShear:torsionShear,designTorsionShear:torsionShear*C.loadFactor,
    serviceTwistDegrees:totalM*bL/(C.E/(2*(1+C.nu))*J)*180/Math.PI,
    I:bI,Z:bZ,J,metalMassKg:bridgeMetalMass(variant),
  });
  const storagePointLoad=bookMass*C.g,deckMass=deckMetalMass(variant),deckWeight=deckMass*C.g;
  const fl=C.deckPitch,tf=variant==='light'?2:8,web=variant==='light'?2:0,h=variant==='light'?6:0;
  const Af=fl*tf,Aw=web*h,ybar=(Af*(h+tf/2)+Aw*h/2)/(Af+Aw);
  const tI=fl*tf**3/12+Af*(h+tf/2-ybar)**2+web*h**3/12+Aw*(h/2-ybar)**2;
  const tZ=tI/Math.max(ybar,h+tf-ybar),dL=C.deckLength;
  // Assign the entire deck self-weight to this one rib as a conservative UDL.
  const tee=member((storagePointLoad*dL/4+deckWeight*dL/8)/tZ,
    storagePointLoad*dL**3/(48*C.E*tI)+5*deckWeight*dL**3/(384*C.E*tI),{I:tI,Z:tZ,centroidFromBottom:ybar,spanMm:dL,flangeWidthMm:fl});
  const skinL=C.deckFreeBay,skinI=C.skinLoadStrip*tf**3/12,skinZ=skinI/(tf/2);
  const skinOwnWeight=metalMass(C.skinLoadStrip*tf*skinL)*C.g;
  const skin=member((storagePointLoad*skinL/4+skinOwnWeight*skinL/8)/skinZ,
    storagePointLoad*skinL**3/(48*C.E*skinI)+5*skinOwnWeight*skinL**3/(384*C.E*skinI),{I:skinI,Z:skinZ,spanMm:skinL,stripWidthMm:C.skinLoadStrip});
  return {
    inputs:{bookMass,angle,thickness,variant,extraMass}, material:{E:C.E,yieldMPa:C.yieldMPa,density:C.density},
    loads:{movingMassKg:movingMass,totalStandMassKg:totalMass,serviceVerticalN:totalF,designVerticalN:totalF*C.loadFactor,
      totalServiceMomentNmm:totalM,totalDesignMomentNmm:totalM*C.loadFactor,heavyShare:C.heavyShare},
    post,bridge,deck:{tee,skin,metalMassKg:deckMass,serviceBookLoadN:storagePointLoad},
    joints:{requiredVerticalLockN:N*C.loadFactor,requiredAngleLockNm:jointM*C.heavyShare*C.loadFactor/1000,
      requiredTotalAngleLockNm:jointM*C.loadFactor/1000,sleeveContactCoupleN:M*C.loadFactor/122,
      description:'하중에서 계산한 요구량. 실제 브레이크/힌지의 제공 용량과 별개.'},
    stability:{bookComY,bookComZ,bookOnlyFrontMarginMm:bookComY-C.groundFront,bookOnlyBackMarginMm:C.groundBack-bookComY,
      description:'수직 책 하중 무게중심의 앞뒤 지지영역 위치만 확인. 완제품 전도 안전계수 아님.'},
    scope:LIGHT_SCOPE,
  };
}

export function lightSweep(variant='light') {
  const cases=[];
  for(const thickness of [25,50])for(const bookMass of [3,4,5]) {
    const max={};
    for(let i=0;i<=4500;i++) {
      const angle=30+i/100,r=calculateLightweight({bookMass,thickness,variant,angle});
      for(const [key,value] of Object.entries({postStress:r.post.designStress,postDeflection:r.post.serviceDeflection,
        bridgeStress:r.bridge.designStress,bridgeDeflection:r.bridge.serviceDeflection,hingeTorque:r.joints.requiredAngleLockNm,
        verticalLock:r.joints.requiredVerticalLockN}))if(!max[key]||value>max[key].value)max[key]={value,angle};
    }
    const result=calculateLightweight({bookMass,thickness,variant,angle:max.postStress.angle});
    cases.push({bookMass,thickness,variant,max,atWorstPost:result});
  }
  return {angleStepDegrees:.01,cases,scope:LIGHT_SCOPE};
}

